  str_season_maze_room_name_boss = "Devorador de sueños",
  str_season_maze_room_name_boss_desc = "Un grupo de villanos viciosos que exclusivamente devoran sueños para alimentarse de las emociones y recuerdos del soñador. Se deslizan en los sueños a través de cualquier abertura que puedan encontrar y causan estragos, provocando un desequilibrio de energía de sueño para atraer al soñador a su sueño.",
  str_season_maze_room_name_ultboss = "Devorador de Sueños Definitivo",
  str_season_maze_room_name_ultboss_desc = "El líder de la escoria, ladrones, asaltantes... y más. ¡Derrotalo para estabilizar la energía del sueño de los sueños!",
  str_season_maze_room_name_battle = "Reino de Sueño Peligroso",
  str_season_maze_room_name_battle_desc = "Un reino de sueños lleno de peligrosas fluctuaciones de energía. Puedes esperar encontrarte con algunos villanos maliciosos vagando en sueños aquí.",
