  str_season_maze_room_name_camp = "Reino de Sueño Seguro",
  str_season_maze_room_name_battle_des = "Lucharás contra enemigos después de entrar en este reino de sueños y tendrás la oportunidad de elegir un Dream Gear tras la victoria.",
  str_season_maze_room_name_event_des = "Se activarán eventos aleatorios después de entrar a este reino de sueños. Algunos eventos requieren sacar 3 Cartas de Adivinación de Sueños y calcular la suma de puntos para determinar si recibirás recompensas.",
  str_season_maze_room_name_res_des1 = "Se obtendrán recompensas de Monedas de Sueño después de entrar a este reino de sueños. Las Monedas de Sueño se pueden intercambiar por artículos. Cuantos más Pasos de Acción se tomen en esta ronda, mayores serán las recompensas.",
  str_season_maze_room_name_res_des2 = "Se obtendrán recompensas de EXP de Sueño después de entrar a este reino de sueños. La EXP de Sueño se puede usar para aumentar el Nivel de Sueño. Cuantos más Pasos de Acción se tomen en esta ronda, mayores serán las recompensas.",
  str_season_maze_room_name_res_des3 = "Las recompensas de Orbe de Sueño se obtendrán después de entrar a este reino de sueños. Los Orbes de Sueño se pueden usar para aumentar tu poder. Cuantos más Pasos de Acción se tomen en esta ronda, mayores serán las recompensas.",
  str_season_maze_room_name_ore_des = "Después de entrar en este Reino de Sueños, los Navegantes pueden enviar a cualquier Aurorian para completar misiones y ganar recompensas. Cuantas más rondas, mayores serán las recompensas. Mientras están enviados, los Aurorians no pueden participar en batallas y volverán automáticamente después de que termine su misión.",
  str_season_maze_room_name_box_des = "Al ingresar a este reino de sueños, los Navegantes pueden elegir una recompensa de varias opciones para obtener.",
  str_season_maze_room_name_round_des = "Al entrar en este reino de sueños, los Navegantes retrasan el asalto del Devorador de Sueños en 1 ronda.",
  str_season_maze_room_name_empty_des = "No se activarán efectos al entrar en este reino de sueños.",
  str_season_maze_room_name_hand_des = "En este reino de sueños, los Navegantes pueden gastar Monedas de Sueño para reiniciar o eliminar las existentes Cartas de Adivinación de Sueños.",
  str_season_maze_room_name_market_des = "En este reino de sueños, los Navegantes pueden intercambiar varios tipos de Orbes de Sueño entre sí.",
  str_season_maze_room_name_camp_des = "Los navegantes pueden recuperarse en este reino de sueños y volverse más fuertes al invocar a los Aurorianos, comprar artículos, adquirir medicinas o resucitar a los Aurorianos. También se pueden infundir Dream Coins en la Dream Forge para desbloquear artículos más poderosos para futuros desafíos.",
  str_season_maze_room_name_bead_market_des = "En este Reino de los Sueños, los Navegantes pueden reclamar una Esfera de Sueño gratis y comprar más si es necesario.",
