  str_season_maze_ore_room_tips_main = "Elige el <color=#A0690E>número de rondas para enviarlos</color>. Cuantas más rondas sean enviados, más <color=#A0690E>recompensas</color> obtendrás. Envía a cualquier Aurorian para recibir recompensas.",
