  str_season_maze_card_step_des_2 = "Avanza <color=#b3790b>{1}-{2}</color> reinos de sueños",
  str_season_maze_card_eft_des_common = "{1} +<color=#b3790b>{2}</color>",
  str_season_maze_card_eft_des_1 = "Obtuve un par de Zapatos Voladores",
  str_season_maze_card_eft_des_2 = "Obtenido una cantidad aleatoria de Interés de Sueño.",
  str_season_maze_card_eft_des_3 = "Copia la Carta de Adivinación del Sueño jugada en la ronda anterior",
  str_season_maze_card_bag_step_des_1 = "Paso de Acción",
  str_season_maze_card_bag_resource_des_1 = "Dream Coins are the smallest units that make up dream energy, as well as the most effective currency in dreams as they can be exchanged for various items within dreams.",
  str_season_maze_card_bag_resource_des_2 = "EXP de sueño. Esto representa el conocimiento y la experiencia que has ganado en sueños. Cuando la EXP de sueño alcanza el estándar para una mejora, el nivel de sueño aumentará, aumentando el nivel de los Aurorians y el equipo y otorgando otras recompensas de recursos.",
  str_season_maze_card_bag_resource_des_3 = "Cyclique. Debes tener suficiente Cyclique con un sueño para asegurarte de que puedes moverte sin problemas en el sueño. Si Cyclique cae a 0, la exploración se terminará automáticamente. Cada ronda de batalla consume 1 punto de Cyclique. En caso de fracaso contra el Devorador de Sueños, también puedes gastar Cyclique para otro intento.",
  str_season_maze_card_bag_resource_des_4 = "Interés de Sueño. El Interés de Sueño representa la cantidad de Monedas de Sueño que se pueden recolectar durante los eventos de sueño. Al final de cada ronda, se realizará un asentamiento y te otorgará la misma cantidad de Monedas de Sueño que el Interés de Sueño.",
  str_season_maze_card_bag_resource_des_5 = "Orbes de Sueño. Estos son recuerdos y emociones dejados por los soñadores originales que han sido envueltos por capas de energía de sueño. Después de ser recogidos, los Orbes de Sueño pueden mejorar el poder de combate en un sueño, ¡así que ten cuidado de no dejar que el Devorador de Sueños los recoja!",
  str_season_maze_card_bag_resource_des_6 = "El número de Cartas de Adivinación de Sueños dibujadas en la próxima ronda +2, hasta +5.",
  str_season_maze_card_bag_resource_des_7 = "Los Zapatos Voladores son un objeto de Ayuda de Sueño formado a partir de energía de sueño desgastada y permiten al usuario avanzar 1 paso más. En esta ronda, cada Paso de Acción de la Carta de Adivinación de Sueños +1.",
  str_season_maze_card_bag_extra_des_1 = "Copia la Carta de Adivinación del Sueño jugada en la ronda anterior",
  str_season_maze_pet_less_one_available = "El último Aurorian no puede ser enviado.",
  str_season_maze_card_giveup = "¿Omitir esta selección de Carta de Adivinación de Sueños?",
  str_season_maze_once_item_info_title = "Artículo de Ayuda de Sueño",
  str_season_maze_once_no_select = "¡Selecciona un Peligroso Reino de Sueños como el objetivo de la Bomba de Sueños!",
  str_season_maze_item_cant_use = "Aún no puedes usar las Cartas de Adivinación de Sueños. Los artículos de Ayuda de Sueño no se pueden usar en este momento.",
  str_season_maze_once_1_name = "Zapatos voladores",
  str_season_maze_once_2_name = "Chorro",
  str_season_maze_once_3_name = "Escudo de seguridad",
  str_season_maze_once_4_name = "Bomba de sueño",
  str_season_maze_once_1_desc = "Después de usar Zapatos Voladores, en esta ronda, +1 Paso de Acción para todas las Cartas de Adivinación de Sueños en tu mano.",
  str_season_maze_once_2_desc = "Después de usar Jet, el número de Pasos de Acción realizados por el Caelestite en esta ronda es la suma de los Pasos de Acción de todas las Cartas de Adivinación de Sueños sacadas en esta ronda, pero las recompensas de recursos de estas Cartas de Adivinación de Sueños no se pueden obtener.",
  str_season_maze_once_3_desc = "Después de usar el Escudo de Seguridad, el Caelestite no jugará más Cartas de Adivinación de Sueños en esta ronda y será teletransportado a un Reino de Sueño Seguro. En el Reino de Sueño Seguro, es posible invocar a los Aurorianos, comprar artículos, curar a los Aurorianos, revivir a los Aurorianos e infundir Monedas de Sueño en la Forja de Sueños.",
  str_season_maze_once_4_desc = "Al usar una Dream Bomb, se puede seleccionar un Dangerous Dream Realm para ser eliminado directamente y se otorgarán las recompensas por eliminar el reino de los sueños.",
  str_season_maze_even_desc_1001 = "Exploras los alrededores con confusión: no hay enemigos, no hay tesoros... nada. Una pared invisible te detiene en seco con un fuerte \"¡Thump!\" \n\n\"Análisis de la situación en progreso... La energía en este reino de sueños fluctúa demasiado salvajemente para determinar la ubicación con precisión.\" La cara de Enlightener se pone al rojo vivo por la operación acelerada. \"Este es un reino de sueños desconocido. El profesor Francis mencionó que le encanta la incertidumbre de este tipo de reino de sueños. Además, a veces aparecerán los restos de la imagen del soñador.\"En otras palabras, podrías encontrarte con tus viejos amigos aquí.\n\n\"Se han determinado tres rutas de salida. Por favor, haz tu elección. Aviso: Diferentes rutas ofrecen diferentes recompensas. Se te sugiere que planees para el peor escenario para evitar arruinar tu experiencia de juego.\"\n\nComo si sintiera tu ansiedad, Enlightener explica inmediatamente, \"El peor resultado es no obtener ninguna recompensa\". Eso es mucho mejor entonces... ¿verdad?",
  str_season_maze_even_desc_1002 = "\"Análisis de la situación en progreso...\" Enlightener está fijado en el aire a su alrededor como si muchas joyas translúcidas se estuvieran moviendo dentro... Aunque no ves nada, sabes que estás en un reino de sueños desconocido de nuevo.\n\n\"Se han determinado tres rutas de salida. Por favor, haz tu elección.\"\n\nComo si quisiera animarte, Enlightener tira de tu camisa y dice en voz baja, \"Tengo la corazonada de que esta vez podrías atrapar Monedas de Sueño.\"",
  str_season_maze_even_desc_1003 = "\"Análisis de la situación en progreso...\" Quizás sea por la emoción y la emoción de la \"incertidumbre\" que sentiste en los anteriores reinos de sueños desconocidos, que estás empezando a esperar los resultados de los cálculos de Enlightener.\n\n\"Resumen: Al igual que el Profesor Francis, has llegado a gustarte los reinos de sueños desconocidos.\"Enlightener parece satisfecho con la conclusión. \"Explicación: Deberías saber a estas alturas que no te engañé. Los juegos en los sueños son bastante interesantes. No, no tengo sentimientos propios, pero puedo deducir cómo se sienten los Viajeros de los Sueños.\"",
  str_season_maze_even_desc_1004 = "Enlightener se agacha y recoge un puñado de tierra.\n\n\"Explicación: El profesor Francis una vez dijo que hay una criatura de corazón blando en el mar que uniría las arenas que se filtran en su cuerpo en lágrimas de agonía hasta que finalmente el dolor se convirtiera en una hermosa perla.\"\n\nEnlightener hace una pausa, pareciendo una chica ordinaria a la que le gustan los cuentos de hadas. \"Hay cosas similares en los sueños.\"",
  str_season_maze_even_desc_1005 = "\"Resumiendo: Las pesadillas son diferentes de los sueños dulces.\"\n\nPor supuesto que lo son. Ni siquiera tienes que pensarlo para decir eso, pero para Enlightener, ella tiene que recopilar innumerables información para formular la misma conclusión.\n\n¿Es esto lo que significa \"Solo en pesadillas el dolor de los soñadores se transformará en Orbe de Sueño\"?!\n\nComienzas a preguntarte si Enlightener sabe lo que significa soñar, e incluso si ella sueña en absoluto.",
  str_season_maze_even_desc_1006 = "\"¡Por aquí, por aquí!\" \n\nEres recibido por una voz fuerte y clara. Es de Eve.\n\nMirás hacia abajo y ves a Eve saltando y agitando sus brazos. \"Oye, ¿has crecido más alto? Es tan injusto, ¿por qué no puedo ser alta?\"\n\nPor supuesto, no está enojada de ninguna manera. \"¡Por eso, solo puedes elegir un regalo!\"",
  str_season_maze_even_desc_1007 = "\"Oh, acabo de notar a la pequeña niña detrás de ti. ¿Quién es ella, tu hermana?\"\n\nAunque esto es solo un remanente del sueño real de Eve, aún te encuentras sin palabras.\n\n\"¡Vaya, qué adorable es ella! ¿Cómo es que la has estado manteniendo lejos de mí?\"\n\nEve presiona su mejilla contra la de Enlightener. \"¡Tenemos que pasar tiempo juntas de ahora en adelante!\"",
  str_season_maze_even_desc_1008 = "\"¡Uf, el picnic finalmente está listo!\"\n\nEve se estira antes de notarte. \"Vaya, eres tú... Me asustaste por un segundo...\"\n\nLe das un pañuelo para que se limpie el sudor brillante de su frente. \"¡Gracias! Lo lavaré antes de devolvértelo, ¿o qué tal si te llevas uno para el camino?\"",
  str_season_maze_even_desc_1009 = "\"Hacha de oro, hacha de plata y simplemente hacha. ¿Cuál es la tuya?\"\n\nEve cierra los ojos, pero aún así la ves echándote un vistazo. Inmediatamente niegas con la cabeza.\n\n\"¿Así que estás diciendo que ninguna de estas es tuya? ¡Qué honesto eres! Como recompensa, elige una como tu favorita y llévatela.\"",
  str_season_maze_even_desc_1010 = "\"¡Justo lo que estaba esperando, alguien con quien jugar a las casitas!\" \n\nEve te mira con alegría, pero luego un destello de timidez cruza sus ojos.\n\n\"Solo somos dos, sin embargo, no suficientes para todos los roles... Sería genial tener un tercero, ¿verdad?\"",
  str_season_maze_even_desc_1011 = "Eve está algo cautivada por las varias cuentas que parecen perlas.\n\nAl notarte, rápidamente desvía su atención y ríe. \"Es maravilloso cómo las bonitas cuentas aparecen cuando me siento particularmente triste. Pero también sé que en realidad me están protegiendo.\"\n\nNunca has visto comportamientos tan maduros de Eve. \"Es cierto que el dolor enseña a las personas a crecer, veo.\"",
  str_season_maze_even_desc_1012 = "Ella parpadea y te mira con curiosidad. \"¿Estás seguro de que quieres intercambiar lo más preciado para ti por estas cuentas en mi mano?\"\n\nInclina la cabeza antes de reírse. \"¡No las confundas con perlas! Para ser honesta, estas podrían ser... mi dolor. ¿Aún quieres hacer el intercambio, en ese caso?\"Al verte asentir, la mirada en sus ojos se suaviza de inmediato. \"Gracias por tomar mi dolor. ¡Nunca me permitiré ser infeliz de nuevo, solo por ti!\"",
  str_season_maze_even_desc_1013 = "Tu cabeza zumba y de repente estás viendo cinco, seis, siete, ocho, nueve Enlighteners...\n\n\"Análisis de la situación en progreso...\" La cara de Enlightener ahora es un borrón, y crees que su voz suena un poco más inquieta y asustada de lo habitual. \"Advertencia, el Viajero de los Sueños debe mantener suficiente Resonancia con el sueño para garantizar la estabilidad.\"Solo cuando sales de tu ensimismamiento, Enlightener explica en retrospectiva, \"Aviso: La estabilidad de un Viajero de Sueños también afecta a la de Enlightener. Para evitar malfunciones por mi parte, por favor mantén la Resonancia con el sueño.\"",
  str_season_maze_even_desc_1014 = "\"Pregunta: ¿Deseas saber por qué el Profesor Francis desarrolló el módulo de Soporte de Sueños?\" \n\nAsientes y Enlightener cierra los ojos como si se esforzara por recordar... Aunque para ella, simplemente está ordenando eones de datos.\"Respuesta: Los Celestitas desterrados fueron atormentados por la histeria. Para curar a los afligidos, el profesor Francis entró en sus sueños como un Viajero de los Sueños. Es altamente peligroso para un Viajero moverse en un sueño y debe tener ayudas para detectar con precisión, así como monitorear, las fluctuaciones de energía.\"\n\n\"Dada esa necesidad, el profesor desarrolló el módulo de Soporte de Sueños para mí.\"",
  str_season_maze_even_desc_1015 = "\"Respuesta: El profesor Francis creía que solo la ciencia podía salvar a los Caelestites. Pero también creía que hay una fuerza misteriosa más allá de la observación y la comprensión...\"\n\n\"No, no es la teología que conoces. Las fuerzas misteriosas son misteriosas porque no pueden ser observadas o estudiadas con la tecnología actual.\"Siempre que se menciona al Profesor Francis, siempre te recuerda el momento en que Enlightener borró el \"caché de tristeza\" del profesor.\n\nEnlightener de repente se pone alerta. \"Análisis de la situación en progreso... Si deseabas que guardara el caché, podrías hacerlo a través de un comando de voz.\"\n\nEso te asusta... ¿Enlightener también está equipado con algún tipo de módulo telepático?",
  str_season_maze_even_desc_1016 = "Enlightener quiere decir algo pero se detiene de inmediato. Parece tener una pregunta pero no puede iniciar la consulta sin una orden.\n\nDespués de obtener tu consentimiento, finalmente pregunta, \"Pregunta: Me gustaría saber, ¿es el mundo exterior igual que el sueño?\"\n\nResulta que Enlightener nunca salió de la torre en la que \"nació\". Le dices que el mundo exterior es más amplio, más extenso, y prometes llevarla a las montañas, los mares... a todos los lugares del mundo.\"Aviso: Hasta entonces, por favor concéntrate en mejorar tus habilidades.\" Enlightener te recuerda estoicamente, aunque los fuegos artificiales explotando en el pequeño cubo detrás de ella muestran sus verdaderos sentimientos.\n\nDe hecho, te has dado cuenta de que Enlightener es más que solo una máquina desde hace algún tiempo.",
  str_season_maze_even_desc_1017 = "Tienes curiosidad sobre qué tipo de sueños ha tenido ella.\n\n\"Recuperando información...\" Ella cierra los ojos y luego los abre lentamente. \"Lo siento, no estás autorizado para acceder a los archivos relevantes.\" Pero si incluso tú no estás autorizado, ¿quién en el mundo lo está?\"Estas son las reglas que mi creador, el Profesor Francis, ha establecido. Dijo que solo al ganar suficiente EXP de Sueño a través de atravesar sueños, uno puede desarrollar la voluntad indomable y la sabiduría extraordinaria para lidiar con los sueños intrincados de los antiguos Celestitas.\"\n\nEnlightener pone una mano en tu hombro. \"Resumiendo: creo que algún día tendrás acceso.\"",
  str_season_maze_even_desc_1018 = "\"Recuperando información...\" Ella nunca ha ocultado nada al responder tus preguntas, pero parece que esta vez tarda más de lo habitual.\n\n\"Lo siento, mi base de datos no contiene información sobre mi fuente de energía. Pero puedes estar seguro, basándome en las evaluaciones de mis registros de operación, no me quedaré sin energía, al menos no mientras estés vivo.\"\n\nNo estás seguro de si preocuparte o relajarte, dada la respuesta ambigua.",
  str_season_maze_even_desc_1019 = "Ya te has dado cuenta de que el sueño es uno que visitaste antes, pero ahora presenta lo que parecen ser instrumentos de Caelestite e incluso el entorno.\"Respuesta: En un sueño, las fluctuaciones de energía varían en diferentes áreas. Para facilitar el movimiento del Caminante de Sueños, he marcado áreas con fluctuaciones idénticas. Dado que mi base de datos solo contiene modelos de Caelestite, todas las fluctuaciones se interpretan y se representan en ese estilo.\"\n\nHace una pausa antes de proceder con cuidado como si hubiera cometido un error. \"Consulta: ¿Debería cambiar la representación para ti?\"\n\nPero esto te parece perfecto.\n\nRealmente te sientes como en casa, al menos aquí.",
  str_season_maze_even_desc_1020 = "Recordando de repente el nautilus en el Obelisco del Retorno, te vuelves para preguntarle a Enlightener sobre ello.\n\nElla cierra los ojos. \"Recuperando información...\"\n\nEsta vez abre los ojos rápidamente. \"Basándome en tu descripción, supongo que te refieres a una concha. Normalmente, un Celestita poseería una o más conchas. La cantidad poseída no reflejaba la riqueza de un Celestita, pero las variedades raras eran muy buscadas, incluso superando sus valores intrínsecos como coleccionables. Te aconsejo que inviertas con prudencia.\"Aunque las conchas han perdido hace mucho su valor según lo perciben los Caelestites ahora, el consejo de Enlightener sigue siendo aplicable.",
  str_season_maze_even_desc_1021 = "Después de aprender que el Nightium es la moneda actual de la tierra, el cubo junto a Enlightener no mostró signos de sorpresa, sin embargo.\n\n¿Ya lo había anticipado?\n\n\"Respuesta: Reconozco que la moneda es un producto natural del desarrollo social, pero no tiene valor para mí.\"\n\n¿Qué es valioso entonces, para ella?Su rostro se vuelve rojo caliente otra vez, pero ahora sabes que es porque sus \"cerebros\" están trabajando horas extras. \"Respuesta: No logré encontrar la respuesta a esta pregunta, pero suponiendo a partir de la información pasada, tu compañía y cumplidos son la moneda más valiosa para mí.\"",
  str_season_maze_even_desc_1022 = "Has recogido algunas cosas en los sueños que podrían ayudarte a explorar los sueños antes, pero no parecían pertenecer a este sueño...\n\n\"Respuesta: La energía puede fluctuar entre los sueños. Aunque los principios son desconocidos, los estudios sugieren que los sueños intercambian energía basándose en ciertas reglas. Esos objetos siguieron el flujo hacia diferentes sueños. Podías tomarlos porque no pertenecían a ningún sueño en particular.\"\n\n¿De dónde podrían ser?Al notar que aún estás perdido, Enlightener respondió, \"Fueron dejados por los Viajeros de Sueños que entraron antes.\"",
  str_season_maze_even_desc_1023 = "He estado en sueños durante mucho tiempo, ¿cuándo terminará esto?\n\nElla se da cuenta de que te estás cansando. \"Puedes tomar un respiro. Restaurar el equilibrio energético en los sueños no es una tarea corta. Por lo general, un sueño tiene muchos niveles. Cuanto más se cierra el soñador al mundo en la realidad, más niveles tiene un sueño. Sin embargo, una vez que la energía se reequilibra, sus mejoras en la vida real también serán obvias.\"Enlightener se acerca más. \"Explicación: Si te sientes cansado, puedo prepararte una bebida caliente en cualquier momento.\"",
  str_season_maze_even_desc_1024 = "A medida que te adentras más en los sueños, te das cuenta de que te estás acostumbrando cada vez más a las reglas.\n\n\"Aviso: Puedes aprovechar las reglas y recordar a los Aurorianos que conoces y convocarlos para que te ayuden. Pero ten en cuenta que no serán reales, y evita pensar que puedes salir impune de cualquier cosa en los sueños. Incluso con mi ayuda, no debes pasar por alto los posibles peligros en un sueño.\"Luego te das cuenta de que Enlightener habla con un tono diferente. \"Lo anterior es un aviso automático activado en ciertas fases por el Módulo de Soporte de Sueños y no refleja la evaluación de Enlightener sobre ti.\"",
  str_season_maze_even_desc_1025 = "La ves de espaldas y el cubo junto a ella está registrando algunos datos...\n\n\"¡Advertencia, no te acerques!\"\n\nAl detectar a alguien acercándose, Enlightener emite una advertencia en un tono agudo, solo para luego darse cuenta de que eres tú y volver el volumen a la normalidad. \"Explicación: Descansa tranquilo, evaluaré tu rendimiento de manera justa y otorgaré la puntuación apropiada.\"Finalmente te das cuenta de que ella ha estado observando cada uno de tus movimientos y puntuándote todo el tiempo!\n\n\"Explicación: Esta es una característica adicional que proporciono para que puedas monitorear mejor tus acciones en los sueños. Te daré recompensas adicionales cada vez que cumplas con un criterio apropiado.\"\n\nBueno, no puedes subestimarla, porque realmente es una entrenadora maestra.",
  str_season_maze_even_desc_1026 = "Bajo su guía, notas que parecen haber muchas partículas brillantes flotando en el aire.\n\n\"Explicación: Son Monedas de Sueño, la unidad más pequeña que compone la energía del sueño. A través de las reglas de los sueños, puedes transformarlas en cualquier cosa que quieras.\"\n\nViendo que todavía es un poco difícil de entender, Enlightener lo explica de otra manera. \"En pocas palabras, las Monedas de Sueño son la moneda aquí. Aunque es mejor recolectar tantas como sea posible, no recomiendo acumularlas.\"",
  str_season_maze_even_desc_1027 = "\"Explicación: Los Devoradores de Sueños errantes continuarán devorando un sueño y construyendo guaridas en las ruinas. Solo eliminando las guaridas la energía puede volver al equilibrio.\"\n\nElla nunca deja de reiterarte las reglas, una y otra vez.\n\n\"Sugiero acumular suficientes Monedas de Sueño antes de enfrentarte a la parte más profunda de una guarida: el Miasma.\"",
  str_season_maze_even_desc_1028 = "Eve está tumbada en el césped con su torso superior apoyado. Te acercas y ves que está leyendo un libro.\n\n\"Ahí estás. Solo estoy leyendo un libro, pero es demasiado difícil para mí entender y me está dando dolor de cabeza.\" Sin embargo, pronto ella está hablando contigo sobre el libro con alegría...\"Sí, lo entiendo ahora que lo has explicado de esa manera. La longitud y la anchura de la vida... Así que eso es lo que significa.\"\n\nPero ella cae de nuevo en la desesperación. \"Pero si debo elegir uno... Qué elección tan difícil. ¿Cuál elegirías tú?\"",
  str_season_maze_even_desc_1029 = "\"Dices que todo tiene un costo... ¿Es eso cierto?\" \n\nEve te mira a los ojos, pero no sabes qué respuesta espera.\n\n\"¿Cuál es el costo del... amor?\" Sacudes la cabeza y le dices a Eve que el amor verdadero es mutuo.\n\nTu respuesta anima a Eve de inmediato. \"Ya veo. ¡Entonces debería devolver amor a todos tanto como pueda!\"",
  str_season_maze_even_desc_1030 = "\"Huff, huff...\"\n\nA pesar de que apenas puede respirar, Eve nunca deja de correr.\n\n\"Estoy... estoy bien... Deja de decirme que pare. Tengo que entrenar y hacer ejercicio para no retrasar a todos!\"\n\nAl verte aún inmóvil, Eve se da la vuelta y guiña un ojo. \"¿Qué haces aún de pie? Vamos, no me digas que ni siquiera puedes alcanzarme!\"",
  str_season_maze_even_option_10011 = "Determinación de Adivinación de Sueños 8: Sortea 1 carta de Adivinación de Sueños de Grado 3 al azar",
  str_season_maze_even_option_10012 = "Sortea 1 Tarjeta de Adivinación de Sueños de Grado 2 al azar",
