  str_season_maze_equip = "Equipa",
  str_season_maze_equipping = "Equipando",
  str_season_maze_synthesis = "Sintetizar",
  str_season_maze_quality = "Calidad",
  str_season_maze_type = "Tipo",
  str_season_maze_intro_title = "Info. de Orbe de Sueño",
  str_season_maze_intro_desc = "Info. de Orbe de Sueño",
  str_season_maze_bead_intro_title_1 = "Efectos del Orbe de Sueño",
  str_season_maze_bead_intro_title_2 = "Nivel de Orbe de Sueño",
  str_season_maze_bead_intro_desc_1 = "1. Hay 3 tipos de Orbes de Sueño: Orbes de Habilidad, Orbes de Mejora y Orbes de Carga. Los Orbes de Habilidad se utilizan para lanzar una habilidad en batalla, los Orbes de Mejora mejoran otros Orbes de Sueño equipados, y los Orbes de Carga te hacen ganar Energía más rápido en las batallas.2. En la batalla, ganas 1 Energía de Orbe de Sueño por cada ficha que los aurorianos mueven y conectan. Si el jugador tiene más Energía que el requerimiento de Energía de los Orbes de Sueño después de conectar las fichas, el jugador lanzará habilidades de Orbe de Sueño en orden de izquierda a derecha.\n3. El requerimiento de Energía del Orbe de Sueño es la suma del requerimiento de Energía de todos los Orbes de Sueño equipados.",
  str_season_maze_bead_intro_desc_2 = "1. Las Esferas de Sueño vienen en 4 niveles y pueden ser mejoradas hasta Esferas de Sueño de 3 estrellas. Cuanto mayor sea el nivel de una Esfera de Sueño, más fuertes serán sus efectos.2. Es posible sintetizar 2 Orbes de Sueño del mismo nivel. Si los Orbes de Sueño sintetizados son el mismo Orbe de Sueño, se garantiza que obtendrás el mismo Orbe de Sueño de un nivel superior. Si los Orbes de Sueño sintetizados son diferentes Orbes de Sueño, obtendrás un Orbe de Sueño aleatorio de un nivel superior.3. Después de que cada desafío de Echoes of a Dream termine, puedes conservar las 5 Dream Orbs de nivel más alto equipadas para el próximo desafío. Cuando se equipan menos de 5 Dream Orbs, se conservarán las Dream Orbs de nivel más alto en tu mochila. Las Dream Orbs retenidas se restablecerán a Lv. 1.",
  str_season_maze_energy = "Requerimiento de energía",
  str_season_maze_bead_equip_desc = "Requisito de Energía: {1}",
