  str_season_maze_autobead_desc1 = "Aplica DoT a los enemigos por adelantado y aplica daño 1 vez adicional.",
  str_season_maze_autobead_desc201 = "Todos los aurorianos aliados pierden 300 HP. Gana 1 Moneda de Sueño por cada auroriano que pierda HP de esta manera. Este efecto no se activará si el HP actual es menor que eso.",
  str_season_maze_autobead_desc202 = "Todos los aliados aurorianos pierden 350 HP. Gana 1 Moneda de Sueño por cada auroriano que pierda HP de esta manera. Este efecto no se activará si el HP actual es menor que eso.",
  str_season_maze_autobead_desc203 = "Todos los aliados aurorianos pierden 400 HP. Gana 1 Moneda de Sueño por cada auroriano que pierda HP de esta manera. Este efecto no se activará si el HP actual es menor que eso.",
  str_season_maze_autobead_desc204 = "Todos los aliados aurorianos pierden 500 HP. Gana 1 Moneda de Sueño por cada auroriano que pierda HP de esta manera. Este efecto no se activará si el HP actual es menor que eso.",
  str_season_maze_autobead_desc301 = "Genera 2 fichas mejoradas en posiciones aleatorias en el campo de batalla.",
  str_season_maze_autobead_desc302 = "Genera 3 fichas mejoradas en posiciones aleatorias en el campo de batalla.",
  str_season_maze_autobead_desc303 = "Genera 4 fichas mejoradas en posiciones aleatorias en el campo de batalla.",
  str_season_maze_autobead_desc304 = "Genera 6 fichas mejoradas en posiciones aleatorias en el campo de batalla.",
  str_season_maze_autobead_desc401 = "Genera 2 Fichas Oscuras en posiciones aleatorias en el campo de batalla.",
  str_season_maze_autobead_desc402 = "Genera 3 fichas oscuras en posiciones aleatorias en el campo de batalla.",
  str_season_maze_autobead_desc403 = "Genera 4 fichas oscuras en posiciones aleatorias en el campo de batalla.",
  str_season_maze_autobead_desc404 = "Genera 6 fichas oscuras en posiciones aleatorias en el campo de batalla.",
  str_season_maze_autobead_desc501 = "Convierte 1 mosaico aleatorio en el campo de batalla en un mosaico cromático.",
  str_season_maze_autobead_desc502 = "Convierte 2 fichas aleatorias en el campo de batalla en fichas cromáticas.",
  str_season_maze_autobead_desc503 = "Convierte 3 fichas aleatorias en el campo de batalla en fichas cromáticas.",
  str_season_maze_autobead_desc504 = "Convierte 4 fichas al azar en el campo de batalla en fichas cromáticas.",
  str_season_maze_autobead_desc601 = "Cuando se activa, gana 1 acumulación de Espíritu de Batalla y 1 Orbe de Acumulación de Energía. Inflige 6,700 de Daño de Área a todos los enemigos después de obtener 3 Orbes de Acumulación de Energía.",
  str_season_maze_autobead_desc602 = "Cuando se activa, gana 1 acumulación de Espíritu de Batalla y 1 Orbe de Acumulación de Energía. Inflige 12,100 de Daño de Área a todos los enemigos después de obtener 3 Orbes de Acumulación de Energía.",
  str_season_maze_autobead_desc603 = "Cuando se activa, gana 1 acumulación de Espíritu de Batalla y 1 Orbe de Acumulación de Energía. Inflige 21,500 de Daño de Área a todos los enemigos después de obtener 3 Orbes de Acumulación de Energía.",
  str_season_maze_autobead_desc604 = "Cuando se activa, gana 1 acumulación de Espíritu de Batalla y 1 Orbe de Acumulación de Energía. Inflige 37,600 de Daño de Área a todos los enemigos después de obtener 3 Orbes de Acumulación de Energía.",
  str_season_maze_autobead_desc701 = "Cuando se activa, invoca 1 barrera que dura 2 rondas. Los ataques normales de los Aurorianos aliados infligen 1,400 de daño fijo adicional cuando están dentro de la barrera.",
  str_season_maze_autobead_desc702 = "Cuando se activa, invoca 1 barrera que dura 2 rondas. Los ataques normales de los Aurorianos aliados infligen 2,500 de daño fijo adicional cuando están dentro de la barrera.",
  str_season_maze_autobead_desc703 = "Cuando se activa, invoca 1 barrera que dura 2 rondas. Los ataques normales de los Aurorianos aliados infligen 4,400 de daño fijo adicional cuando están dentro de la barrera.",
  str_season_maze_autobead_desc704 = "Cuando se activa, invoca 1 barrera que dura 2 rondas. Los ataques normales de los Aurorianos aliados infligen un daño fijo adicional de 7,600 cuando están dentro de la barrera.",
  str_season_maze_autobead_desc8 = "Ataca al enemigo más cercano con Meteoritos, infligiendo daño a 5 casillas en forma de cruz e infligiendo Aturdimiento y Derretido a los enemigos golpeados.",
  str_season_maze_autobead_desc9 = "Ataca a todos los enemigos con relámpagos, infligiendo daño a un solo objetivo.",
  str_season_maze_autobead_desc10 = "Dispara flechas al enemigo con el HP más bajo, infligiendo daño a un solo objetivo.",
  str_season_maze_autobead_desc11 = "Lanza una bola de fuego al enemigo con el HP más alto, infligiendo daño a un solo objetivo.",
  str_season_maze_autobead_desc12 = "Lanza una carta mágica al enemigo más cercano, infligiendo daño a un solo objetivo.",
  str_season_maze_autobead_desc13 = "Libera una manada de lobos para atacar al objetivo más lejano, infligiendo Daño de Área en el camino.",
  str_season_maze_autobead_desc1401 = "Desbloquea el Módulo de Mejora de Algoritmo. Gana 5 puntos de sobrecarga cuando se activa.",
  str_season_maze_autobead_desc1402 = "Desbloquea el Módulo de Mejora de Algoritmo. Gana 10 puntos de sobrecarga cuando se activa.",
  str_season_maze_autobead_desc1403 = "Desbloquea el Módulo de Mejora de Algoritmo. Gana 15 puntos de sobrecarga cuando se activa.",
  str_season_maze_autobead_desc1404 = "Desbloquea el Módulo de Mejora de Algoritmo. Gana 20 puntos de sobrecarga cuando se activa.",
  str_season_maze_autobead_desc15 = "Invoca rayos para atacar 8 áreas de 2×2 en el campo de batalla y gana Puntos de Sobrecarga cada vez que se golpea a un enemigo.",
  str_season_maze_autobead_desc16 = "Invoca una ventisca para atacar a todos los enemigos en el campo de batalla, infligiendo daño a un solo objetivo e imponiendo Lentitud.",
  str_season_maze_autobead_desc17 = "Provoca una explosión para atacar a todos los enemigos en el campo de batalla, infligiendo daño a un solo objetivo e infligiendo Ceguera.",
  str_season_maze_autobead_desc18 = "Invoca un espíritu maligno para atacar a todos los enemigos en el campo de batalla, infligiendo daño a un solo objetivo e infundiendo miedo. Cuanto más cerca estén los enemigos, mayor será el daño infligido, hasta un aumento del 100%.",
  str_season_maze_autobead_desc19 = "Provoca una lluvia corrosiva en objetivos cercanos, infligiendo Daño de Área a 13 mosaicos en forma de diamante e infligiendo Envenenamiento.",
  str_season_maze_autobead_desc2001 = "Restaura 400 HP a todos los Aurorians en el equipo y activa todos los objetos que se pueden recoger en el campo de batalla.",
  str_season_maze_autobead_desc2002 = "Restaura 700 HP a todos los Aurorians en el equipo y activa todos los objetos que se pueden recoger en el campo de batalla.",
  str_season_maze_autobead_desc2003 = "Restaura 1,200 HP a todos los Aurorians en el equipo y activa todos los objetos que se pueden recoger en el campo de batalla.",
  str_season_maze_autobead_desc2004 = "Restaura 2,000 PS a todos los Aurorians en el equipo y activa todos los objetos que se pueden recoger en el campo de batalla.",
  str_season_maze_autobead_desc21 = "Las orbes de habilidad de daño infligen 1 pila de Envenenado al golpear.\nCuando se equipan múltiples Orbes de Sueño del mismo nombre, solo 1 tendrá efecto.",
  str_season_maze_autobead_desc22 = "Las orbes de habilidad de daño infligen 1 pila de Quemado al golpear.\nCuando se equipan varias Orbes de Sueño con el mismo nombre, solo 1 tendrá efecto.",
  str_season_maze_autobead_desc23 = "Las orbes de habilidad de daño infligen 1 pila de Sangrado al golpear.\nCuando se equipan múltiples Orbes de Sueño del mismo nombre, solo 1 tendrá efecto.",
  str_season_maze_autobead_desc2104 = "Las orbes de habilidad de daño infligen 2 acumulaciones de Envenenado al golpear.\nCuando se equipan varias Orbes de Sueño del mismo nombre, solo 1 tendrá efecto.",
  str_season_maze_autobead_desc2204 = "Las orbes de habilidad de daño infligen 2 acumulaciones de Quemar al golpear.\nCuando se equipan varias Orbes de Sueño con el mismo nombre, solo 1 tendrá efecto.",
  str_season_maze_autobead_desc2304 = "Las orbes de habilidad de daño infligen 2 acumulaciones de Sangrado al golpear.\nCuando se equipan varias Orbes de Sueño con el mismo nombre, solo 1 tendrá efecto.",
  str_season_maze_autobead_desc2401 = "-10% de requerimiento de energía para otros Orbes de Sueño.",
  str_season_maze_autobead_desc2402 = "-15% de requerimiento de energía para otros Orbes de Sueño.",
  str_season_maze_autobead_desc2403 = "-20% de requerimiento de energía para otros Orbes de Sueño.",
  str_season_maze_autobead_desc2404 = "-25% de requerimiento de energía para otros Orbes de Sueño.",
  str_season_maze_autobead_desc2501 = "+15% de tasa de críticos y +20% de daño crítico para orbes de habilidad de daño.",
  str_season_maze_autobead_desc2502 = "+20% de Tasa de Críticos y +30% de Daño Crítico para orbes de habilidad de daño.",
  str_season_maze_autobead_desc2503 = "+25% de tasa de críticos y +40% de daño crítico para orbes de habilidades de daño.",
  str_season_maze_autobead_desc2504 = "+30% de Tasa de Críticos y +50% de Daño Crítico para orbes de habilidad de daño.",
  str_season_maze_autobead_desc2601 = "+15% de Tasa de Acertado y +15% de Tasa de Combo para orbes de habilidad de daño.\nCuando se equipan múltiples Orbes de Sueño con el mismo nombre, solo 1 tendrá efecto.",
  str_season_maze_autobead_desc2602 = "+20% de Tasa de Acertado y +20% de Tasa de Combo para orbes de habilidad de daño.\nCuando se equipan múltiples Orbes de Sueño del mismo nombre, solo 1 tendrá efecto.",
  str_season_maze_autobead_desc2603 = "+25% de Tasa de Acertado y +25% de Tasa de Combo para orbes de habilidad de daño.\nCuando se equipan múltiples Orbes de Sueño del mismo nombre, solo 1 tendrá efecto.",
  str_season_maze_autobead_desc2604 = "+30% de Tasa de Acertado y +30% de Tasa de Combo para orbes de habilidad de daño.\nCuando se equipan múltiples Orbes de Sueño del mismo nombre, solo 1 tendrá efecto.",
  str_season_maze_autobead_desc2701 = "+20% de fluctuación de daño para orbes de habilidad de daño.",
